async function compressParticles() {
    await wait(850);
    const particles = [...particleField.children];

    particles.forEach((particle, i) => {
        const radius = parseFloat(particle.style.getPropertyValue("--radius"));
        const angle = parseFloat(particle.style.getPropertyValue("--angle"));

        particle.style.setProperty("--radius2", `${radius}px`);
        particle.style.setProperty("--angle2", `${angle + Math.random() * 90}deg`);

        setTimeout(() => {
            particle.classList.remove("orbit");
            particle.classList.add("compress");
        }, Math.random() * 450 + i * .7);
    });
}

function spawnWhiteHoleMatter(count = 150) {
    matterOutLayer.innerHTML = "";

    for (let i = 0; i < count; i++) {
        const p = document.createElement("div");
        const angle = Math.random() * 360;
        const distance = 220 + Math.random() * 470;
        const duration = 850 + Math.random() * 900;
        const size = 1.5 + Math.random() * 6;

        p.className = "matter-out";
        p.style.setProperty("--angle", `${angle}deg`);
        p.style.setProperty("--distance", `${distance}px`);
        p.style.setProperty("--duration", `${duration}ms`);
        p.style.setProperty("--size", `${size}px`);

        matterOutLayer.appendChild(p);

        setTimeout(() => {
            p.classList.add("active");
