.card-img-wrapper img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.card:hover .card-img-wrapper img {
  transform: scale(1.06);
}

/* Pack Body */
.card-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  flex: 1;
  justify-content: space-between;
  gap: 12px;
  background: linear-gradient(180deg, #16121f 0%, #100d16 100%);
}

.card-title {
  font-family: 'Cinzel', serif, system-ui;
  font-size: 16px;
  font-weight: 700;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.card-footer {
  position: relative;
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  padding-top: 10px;
}

.card-note {
  font-size: 11px;
  color: var(--note-color, #9c93a8);
  font-style: italic;
  line-height: 1.3;
  transition: color 0.2s ease;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

/* Action Button Row */
.button-row {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  animation: buttonRowFadeIn 0.2s ease-out;
}

@keyframes buttonRowFadeIn {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.card-button {
  flex: 1;
  padding: 9px 14px;
  border-radius: 10px;
  font-family: 'Cinzel', serif, system-ui;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.5px;
  color: #000000;
  background: #ffd86b;
  border: 1px solid rgba(255, 255, 255, 0.3);
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(255, 216, 107, 0.3);
  transition: all 0.15s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.card-button:hover:not(:disabled) {
  background: #ffe391;
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(255, 216, 107, 0.45);
}

.card-button:active:not(:disabled) {
  transform: translateY(1px);
}

.card-button:disabled {
  background: #2a2238;
  color: #6d5f7f;
  border-color: #3b304f;
  cursor: not-allowed;
  box-shadow: none;
}

