  max-height: 220px;
  overflow-y: auto;
  margin-bottom: 10px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.total-dict-item {
  font-family: monospace;
  font-size: 11px;
  display: flex;
  justify-content: space-between;
