// 1. Check ticket or disc currency availability and consume
let hasTicket = false;
if (deck.ticketType === 'angel-roll' && inv.angelRollTickets >= totalCost) {
  inv.spendAngelTickets(totalCost);
  hasTicket = true;
} else if (deck.ticketType === 'solar-roll' && inv.solarRollTickets >= totalCost) {
  inv.spendSolarTickets(totalCost);
  hasTicket = true;
} else if (deck.ticketType === 'codex-roll' && inv.codexRollTickets >= totalCost) {
  inv.spendCodexTickets(totalCost);
  hasTicket = true;
} else if (deck.ticketType === 'discs') {
  const vinylDiscs = useVinylStore.getState().discs || inv.discs || 0;
  if (vinylDiscs >= totalCost) {
    inv.spendDiscs(totalCost);
    useVinylStore.getState().spendDiscs(totalCost);
    hasTicket = true;
  }
}

if (!hasTicket) {
  return null;
}

// 2. Execute multi-roll via compiled engine
const { items, dict } = executePackRoll(deck, mult);

// 3. Inject energy cores if any & accumulate cross-app resources
let newReserves = { ...get().energyReserves };
let totalDnaReward = 0;
let totalRedOrbsReward = 0;
let totalTimeRewardSeconds = 0;

for (const item of items) {
  if (item.category === 'energy-core' && item.energyCores) {
    for (const core of item.energyCores) {
      newReserves[core.attribute] = (newReserves[core.attribute] || 0) + core.amount;
    }
  }
  if (item.dnaReward) {
    totalDnaReward += item.dnaReward;
  }
  if (item.redOrbsReward) {
    totalRedOrbsReward += item.redOrbsReward;
  }
  if (item.timeRewardSeconds) {
    totalTimeRewardSeconds += item.timeRewardSeconds;
  }
}

// 4. Update Arc Jurassic & Universal Currency in Backend/Stores if present
if (totalDnaReward > 0 || totalRedOrbsReward > 0 || totalTimeRewardSeconds > 0) {
  // Universal Time
  if (totalTimeRewardSeconds > 0) {
    useCurrencyStore.getState().earnTime(totalTimeRewardSeconds);
  }

  // Arc Jurassic SQLite Backend Update
  fetchArcResources().then((currentArc) => {
    const updatedDna = (currentArc.dna?.amount || 0) + totalDnaReward;
    const updatedRedOrbs = (currentArc.red_orbs?.amount || 0) + totalRedOrbsReward;
    const updatedJurassicTime = (currentArc.jurassic_time?.amount || 0) + totalTimeRewardSeconds;

    persistArcResources({
      dna: { amount: updatedDna, unit: 'dna', name: 'DNA', icon: 'https://cdn.paleo.gg/games/jwtg/images/resource/dna.png' },
      red_orbs: { amount: updatedRedOrbs, unit: 'orbs', name: 'Red Orbs', icon: 'https://cdn.paleo.gg/games/jwtg/images/hybrid-type/super-hybrid.png' },
      jurassic_time: { amount: updatedJurassicTime, unit: 'seconds', name: 'Jurassic Time', icon: 'https://cdn.paleo.gg/games/jwtg/images/stats/speed.png' },
    }).catch((err) => {
      console.error('[GoldenHourStore] Failed to sync Arc resources:', err);
    });
  }).catch((err) => {
    console.error('[GoldenHourStore] Failed to fetch Arc resources for update:', err);
  });
}

