  const baseKey = resolved
    .replace(/\s*\([^)]*\)/g, '')
    .replace(/\s+x\d+$/i, '')
    .replace(/\s+\d+u$/, '')
    .replace(/\s+\d+\.\.\.\d+$/, '')
    .trim();

