                  {card.Cards} Cards
                </div>

                {/* Ticket / Disc Cost Badge */}
                <div className="absolute top-3 left-3 px-2.5 py-1 rounded-lg bg-[#120f18]/85 border border-white/20 text-[11px] font-mono text-white flex items-center gap-1 shadow-lg backdrop-blur-md">
