                  <span>{card.ticketCost} {card.ticketType === 'discs' ? 'DISCS' : card.ticketType.split('-')[0].toUpperCase()}</span>
                </div>
              </div>

              {/* Pack Body (Centered Horizontally) */}
              <div className="card-body">
                <div className="w-full text-center">
                  <div className="card-title">
                    <span>{card.Title}</span>
                  </div>
                  <div className="text-[11px] font-mono text-[#8c7a9e] mt-1 text-center">
                    Available: <strong className={canAfford ? 'text-emerald-400' : 'text-rose-400'}>{availableTickets}</strong>
                  </div>
                </div>

                {/* Pack Footer */}
                <div className="card-footer">
                  <div
                    className="card-note"
                    style={{
                      '--note-color': isSelected || isHovered ? 'transparent' : '#9c93a8',
                    } as React.CSSProperties}
                  >
                    <i>{card.Note}</i>
                  </div>

                  {(isSelected || isHovered) && (
                    <div className="button-row" onClick={(e) => e.stopPropagation()}>
                      <button
                        className="card-button"
                        disabled={!canAfford}
                        style={{
                          backgroundColor: canAfford ? (card.Button?.startsWith('#') ? card.Button : '#ffd86b') : undefined,
                        }}
                        onClick={() => onRoll(card)}
                      >
                        <Sparkles className="w-4 h-4" />
                        <span>{canAfford ? buttonLabel : 'Need Tickets'}</span>
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default GachaLobby;

