const handleUpdateProgress = async (prog: UserProgress) => {
  setUserProgress(prog);
  const totalFero = calcUserTotalFerocity(objects, prog);
  const top3 = calcUserTop3Ferocity(objects, prog);
  setTotalArmyFerocity(totalFero);
